#include <vector>

class Solution {
public:
    std::vector<int> targetIndices(std::vector<int>& nums, int target) {
        int less_count = 0;
        int equal_count = 0;
        for (int x : nums) {
            if (x < target) {
                less_count++;
            } else if (x == target) {
                equal_count++;
            }
        }

        std::vector<int> result;
        result.reserve(equal_count);
        for (int i = 0; i < equal_count; ++i) {
            result.push_back(less_count + i);
        }
        return result;
    }
};
